use verus::prelude::*;

verus! {
    pub fn binary_search(v: &Vec<u64>, k: u64) -> usize
        // preconditions
        requires
            // the array is nonempty
            v.len() > 0,
            // sorted in non‐decreasing order
            forall |i: usize| i + 1 < v.len() ==> v[i] <= v[i + 1],
            // k actually appears somewhere
            exists |j: usize| j < v.len() && v[j] == k,
        // postcondition
        ensures |res: usize| res < v.len() && v[res] == k,
    {
        let n = v.len();
        // search interval is [lo..=hi]
        let mut lo: usize = 0;
        let mut hi: usize = n - 1;

        // loop until we find k
        while lo <= hi
            invariant
                // bounds are respected
                lo <= hi &&
                hi < n,
            invariant
                // k lives somewhere in [lo..=hi]
                exists |j: usize| lo <= j && j <= hi && v[j] == k,
            // each iteration strictly shrinks the interval size
            decreases (hi - lo) + 1,
        {
            let mid = lo + (hi - lo) / 2;
            if v[mid] < k {
                // k cannot be at or below mid
                lo = mid + 1;
            } else if v[mid] > k {
                // k cannot be at or above mid
                // (mid > lo because lo<=hi and mid=(lo+hi)/2)
                hi = mid - 1;
            } else {
                // we found it
                return mid;
            }
        }

        // By our invariants this point is unreachable
        unreachable!();
    }
}